public class VolumeCalculator extends AreaCalculator {
    public VolumeCalculator(List<Shape> shapes) {
        super(shapes);
    }

    @Override
    public double sum() {
        double totalVolume = 0;
        for (Shape shape : shapes) {
            totalVolume += shape.area();
        }
        return totalVolume;
    }
}

suggestion_code:
public class VolumeCalculator implements Calculator {
    private List<SolidShape> shapes;

    public VolumeCalculator(List<SolidShape> shapes) {
        this.shapes = shapes;
    }

    public double sum() {
        double totalVolume = 0;
        for (SolidShape shape : shapes) {
            totalVolume += shape.volume();
        }
        return totalVolume;
    }
}
